import { consultarEmpresaService } from './service.mjs';

export async function handler(event) {
  const empresaId = Number(event.pathParameters.empresaId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarEmpresaService(empresaId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarEmpresaRepository, consultarEmpresaRepository } from './repository.mjs';

export async function consultarEmpresaService(empresaId, minimo) {
  const empresa = await buscarEmpresaRepository(empresaId);
  if (!empresa) throw new Error('Empresa no encontrado');
  const proyectos = await consultarEmpresaRepository(empresaId, minimo);
  return { empresa, proyectos };
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_PROYECTO, MODELO_EMPRESA } from '../../models/empresa-proyecto.model.mjs';

export async function buscarEmpresaRepository(empresaId) {
  const { Item } = await MODELO_EMPRESA.build(EntityRepository).get(
    { empresaId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarEmpresaRepository(empresaId, minimo) {
  const { Items = [] } = await MODELO_PROYECTO.build(EntityRepository).query(
    { index: 'PorEmpresa', partition: empresaId },
    { filters: { Proyecto: { attr: 'horasEstimadas', gte: minimo } } }
  );
  return Items;
}
